// apps/web/lib/demo-otp.ts
// ============================================================================
// OTP core — code format, generation, TTL policy (+ legacy demo derivation).
//
// Track A (default) — REAL EMAIL OTP. A 6-digit CSPRNG code is generated by
// `generateOtpCode()`, hashed with HMAC-SHA256 (`lib/otp-crypto.ts`) and
// persisted to `verification_attempts` (`lib/otp-store.ts`) with a 5-minute
// TTL (`expires_at`). The plaintext code exists only in the request handler's
// memory and inside the Resend email (`lib/otp-email.ts`). It is never written
// to the database and never printed to a log.
//
// Track B (escape hatch) — when Resend is NOT configured *and*
// `NEXT_PUBLIC_AUTH_MODE === 'demo'`, `/api/auth/request-otp` falls back to a
// deterministic per-email code surfaced in the Demo OTP panel, so the flow
// still completes offline. Configuring `RESEND_API_KEY` promotes the platform
// onto Track A automatically, even while `AUTH_MODE` is still `'demo'`.
//
// Supabase's built-in email provider cannot serve Track A on its own: it only
// delivers to organization team members (2 emails/hour project-wide cap), so
// real student inboxes require the direct Resend API. See docs/OTP_DIAGNOSIS.md.
//
// This module stays pure and isomorphic (Web Crypto only, no `node:` imports)
// so the demo panel can re-derive the same code client-side. Anything that
// needs a server secret — hashing, comparison — lives in `lib/otp-crypto.ts`.
// ============================================================================

/** Real OTP lifetime: 5 minutes from generation. */
export const OTP_TTL_SECONDS = 5 * 60;
export const OTP_TTL_MS = OTP_TTL_SECONDS * 1000;

/** OTP length and numeric range (100000–999999 so the code is always 6 digits). */
export const OTP_LENGTH = 6;
export const OTP_CODE_OFFSET = 100000;
export const OTP_CODE_SPACE = 900000;

/** Verification attempt budget per challenge, and the resend cooldown per email. */
export const OTP_MAX_ATTEMPTS = 5;
export const OTP_RESEND_COOLDOWN_SECONDS = 60;

/** Public in demo mode only — never a secret used for real account security. */
export const DEMO_OTP_SALT = process.env.NEXT_PUBLIC_DEMO_OTP_SALT ?? 'campus360-demo-otp-salt';

/** @deprecated Track B only. Real codes use `OTP_TTL_MS`. */
export const DEMO_OTP_TTL_MS = OTP_TTL_MS;

export function isDemoAuthMode(): boolean {
  return process.env.NEXT_PUBLIC_AUTH_MODE === 'demo';
}

/** Draw a uniformly distributed integer in [0, OTP_CODE_SPACE) from the CSPRNG. */
function randomOtpOffset(): number {
  const webcrypto = globalThis.crypto;
  if (!webcrypto?.getRandomValues) {
    // Never degrade to Math.random() for an authentication secret.
    throw new Error('Web Crypto (crypto.getRandomValues) is unavailable — refusing to generate a weak OTP.');
  }
  const buffer = new Uint32Array(1);
  const rejectionLimit = Math.floor(0x100000000 / OTP_CODE_SPACE) * OTP_CODE_SPACE;
  let draw = 0;
  do {
    webcrypto.getRandomValues(buffer);
    draw = buffer[0];
  } while (draw >= rejectionLimit); // rejection sampling removes modulo bias
  return draw % OTP_CODE_SPACE;
}

/**
 * Cryptographically random 6-digit code (100000–999999).
 * `crypto.getRandomValues` with rejection sampling — no `Math.random()`.
 */
export function generateOtpCode(): string {
  return String(OTP_CODE_OFFSET + randomOtpOffset());
}

export function isOtpCodeFormat(value: unknown): value is string {
  return typeof value === 'string' && new RegExp(`^\\d{${OTP_LENGTH}}$`).test(value);
}

/** ISO-8601 expiry for a freshly issued challenge (defaults to +5 minutes). */
export function otpExpiresAt(from: number = Date.now(), ttlMs: number = OTP_TTL_MS): string {
  return new Date(from + ttlMs).toISOString();
}

/** A missing/unparsable expiry is treated as expired (fail closed). */
export function isOtpExpired(expiresAt: string | Date | null | undefined, now: number = Date.now()): boolean {
  if (!expiresAt) return true;
  const time = typeof expiresAt === 'number' ? expiresAt : new Date(expiresAt).getTime();
  return Number.isNaN(time) ? true : time <= now;
}

/** Whole seconds of validity left — 0 once expired. Used for API/UI hints. */
export function remainingOtpSeconds(expiresAt: string | Date | null | undefined, now: number = Date.now()): number {
  if (!expiresAt) return 0;
  const time = typeof expiresAt === 'number' ? expiresAt : new Date(expiresAt).getTime();
  if (Number.isNaN(time)) return 0;
  return Math.max(0, Math.floor((time - now) / 1000));
}

// ---------------------------------------------------------------------------
// Track B — deterministic demo code (SHA-256(salt:email) → 6 digits).
// Retained only so previews/local runs without SMTP can complete sign-up.
// ---------------------------------------------------------------------------

function toHex(buffer: ArrayBuffer): string {
  return [...new Uint8Array(buffer)].map((byte) => byte.toString(16).padStart(2, '0')).join('');
}

/**
 * Deterministic 6-digit code for an email address (100000–999999).
 * Same input ⇒ same code, in the browser and on the server.
 */
export async function computeDemoOtp(email: string, salt: string = DEMO_OTP_SALT): Promise<string> {
  const normalized = email.trim().toLowerCase();
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(`${salt}:${normalized}`));
  const value = parseInt(toHex(digest).slice(0, 8), 16) % OTP_CODE_SPACE;
  return String(value + OTP_CODE_OFFSET);
}

/** @deprecated Track B alias of `otpExpiresAt`. */
export function demoOtpExpiresAt(from: number = Date.now()): string {
  return otpExpiresAt(from, DEMO_OTP_TTL_MS);
}

/** Mask an address before it reaches a log line: `stu***@du.ac.bd`. */
export function redactEmail(email: string): string {
  const [local = '', domain = ''] = email.split('@');
  if (!domain) return '***';
  const visible = local.slice(0, 3);
  return `${visible || '*'}***@${domain}`;
}
